import{c as e,Z as o,Q as r,j as s,m as n,o as t}from"./chunks/framework.DOi4mjdC.js";const b=JSON.parse('{"title":"伐檀","description":"","frontmatter":{"title":"伐檀","author":"佚名","dynasty":"先秦"},"headers":[],"relativePath":"books/shici/shijing/10.md","filePath":"books/shici/shijing/10.md"}'),u={name:"books/shici/shijing/10.md"};function h(p,i,c,q,d,_){const a=o("PoemAuthor"),l=o("PoemNav");return r(),s("div",null,[i[0]||(i[0]=n('<h1 id="伐檀" tabindex="-1">伐檀 <a class="header-anchor" href="#伐檀" aria-label="Permalink to &quot;伐檀&quot;">​</a></h1><p><strong>[先秦] 佚名</strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>坎坎伐檀兮，置之河之干兮，河水清且涟猗。不稼不穑，胡取禾三百廛兮？不狩不猎，胡瞻尔庭有县貆兮？彼君子兮，不素餐兮！</p><p>坎坎伐辐兮，置之河之侧兮，河水清且直猗。不稼不穑，胡取禾三百亿兮？不狩不猎，胡瞻尔庭有县特兮？彼君子兮，不素食兮！</p><p>坎坎伐轮兮，置之河之漘兮，河水清且沦猗。不稼不穑，胡取禾三百囷兮？不狩不猎，胡瞻尔庭有县鹑兮？彼君子兮，不素飧兮！</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>坎坎：伐木声</li><li>檀：檀树，木质坚硬</li><li>干：岸</li><li>涟：水波纹</li><li>猗：语气词</li><li>稼：耕种</li><li>穑：收割</li><li>胡：为什么</li><li>廛：通&quot;缠&quot;，束</li><li>狩：打猎</li><li>瞻：看见</li><li>县：通&quot;悬&quot;，悬挂</li><li>貆：兽名，即猪獾</li><li>素餐：白吃饭</li><li>辐：车轮上的辐条</li><li>直：平直</li><li>亿：通&quot;繶&quot;，束</li><li>特：三岁的兽</li><li>漘：水边</li><li>沦：小波纹</li><li>囷：圆形的谷仓</li><li>鹑：鹌鹑</li><li>飧：熟食</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>坎坎地砍伐檀树啊，把它放在河岸边啊，河水清澈泛着波纹。不耕种不收割，为什么拿走三百束禾？不打猎不射箭，为什么看见你的庭院里挂着猪獾？那些君子啊，不是白吃饭的啊！</p><p>坎坎地砍伐辐条啊，把它放在河旁边啊，河水清澈泛着直波。不耕种不收割，为什么拿走三百束禾？不打猎不射箭，为什么看见你的庭院里挂着大兽？那些君子啊，不是白吃饭的啊！</p><p>坎坎地砍伐车轮啊，把它放在河水边啊，河水清澈泛着沦波。不耕种不收割，为什么拿走三百仓禾？不打猎不射箭，为什么看见你的庭院里挂着鹌鹑？那些君子啊，不是白吃饭的啊！</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是《诗经》中的名篇，描写了一群伐木者对不劳而获者的质问和讽刺，表达了劳动者对剥削者的不满，是中国古代现实主义诗歌的代表作。</p><p>全诗三章，结构相似，反复咏唱。每章都以伐木的劳动场景开头，&quot;坎坎伐檀兮&quot;&quot;坎坎伐辐兮&quot;&quot;坎坎伐轮兮&quot;，写劳动者辛勤的劳动。然后以&quot;置之河之干兮&quot;等句，写劳动后的休息场景，河水清澈，环境优美。</p><p>接着，诗人以一连串的质问，表达了对剥削者的不满。&quot;不稼不穑，胡取禾三百廛兮？不狩不猎，胡瞻尔庭有县貆兮？&quot;劳动者辛勤耕作、打猎，却一无所获；而那些不劳动的人，却占有大量的粮食和猎物。这种鲜明的对比，揭示了社会的不公。</p><p>最后以&quot;彼君子兮，不素餐兮&quot;作结，以反讽的语气，表达了对剥削者的批判。&quot;不素餐&quot;本是对君子的赞美，在这里却成了对剥削者的讽刺。</p><p>全诗语言质朴，感情强烈，将劳动者的不满和批判表现得淋漓尽致，是中国古代现实主义诗歌的典范之作。</p>',18)),t(a,{name:"《诗经》",years:"西周初年至春秋中叶",desc:"中国最早的诗歌总集，收录了西周初年至春秋中叶（前11世纪至前6世纪）的诗歌305篇，分为“风”“雅”“颂”三部分。《诗经》内容丰富，反映了周代社会生活的方方面面，是中国现实主义文学的源头。",link:"/books/shici/shijing","is-shijing":""}),t(l)])}const f=e(u,[["render",h]]);export{b as __pageData,f as default};
